/* ─ Nueva misión · MVP (sin IA ni tratamiento: RF-21 y RF-26 son «después») ─ */
P.m('Nueva misión · MVP',phone(`${mback('Nueva misión')}${card(`<div class="h3">¿Qué quieres conseguir?</div>${Object.values(TYPES).map(([t,n,l],i)=>card(row(t,n,l,['Hasta que asistas','Autorización y reclamo','De la orden al resultado','Todas tus sesiones'][i],radio(i===2)),'tight',i===2?'border-color:var(--b5);background:var(--b50)':'')).join('')}`)}${card(field('¿Qué examen?',{val:'Resonancia magnética de rodilla'}))}`,{bar:btn('Crear misión','block')}),'v2.17 · Variante del MVP: solo los cuatro tipos y el dato mínimo. La vía con IA (RF-21) y el tratamiento (RF-26) quedan para después; ver «Nueva misión · después».');

/* tratamientos */
const tcard=(n,d,st,stc,items,sel)=>card(`<div class="row">${tile('vi','activity')}<div class="grow"><div class="t">${n}</div><div class="s">${d}</div></div>${st?chip(st,stc):''}</div><div class="row g8 wrap">${items}</div>`,'tight',sel?'border-color:var(--b5)':'');
