P.m('Tratamientos',phone(`${mback('Tratamientos',btn('Crear','sm',ic('plus',15,'#fff',2.6)))}${search('Buscar tratamiento')}${seg(['Activos','Inactivos','Completados'],0)}${tcard('Rodilla derecha','Desde 10 oct · Ortopedia','','',chip('1 misión','gray',ic('route',12))+chip('2 medicamentos','gray')+chip('3 documentos','gray'))}${tcard('Diabetes tipo 2','Desde mar 2024','','',chip('Metformina','gray')+chip('4 citas','gray')+chip('12 check-ins','gray'))}${tcard('Hipertensión','Desde ene 2023','','',chip('Losartán','gray')+chip('2 citas','gray'))}`,{tab:'mas'}));
P.m('Nuevo tratamiento',phone(`${mback('Tratamientos')}${search('Buscar tratamiento')}${tcard('Rodilla derecha','Desde 10 oct · Ortopedia','','',chip('1 misión','gray',ic('route',12)))}`,{tab:'mas',over:sheet(`${sheetHead('vi','activity','TRATAMIENTOS','Nuevo tratamiento')}${field('Nombre',{ph:'Ej: Migraña, Alopecia, Dolor lumbar',focus:true})}${field('Descripción (opcional)',{ph:'Ej: Dolor al subir escaleras',area:true})}<div class="row g10"><div class="grow">${field('Inicio',{icon:'calendar',val:'Hoy, 3 nov'})}</div><div class="grow">${field('Fin (opcional)',{icon:'calendar',ph:'Ej: 30 nov'})}</div></div>${btn('Crear tratamiento','block')}`)}),'v2 · Hoja (pocos campos). Un tratamiento nuevo siempre empieza activo, así que ya no se pide el estado.');
const tdetail=()=>`${tsec('Misiones','route','b',row('gray','route','Realizar tu resonancia de rodilla','Paso 2 de 4',''))}${tsec('Medicamentos','pill','am',row('gray','pill','Ibuprofeno 400 mg','Cada 8 horas · hasta 15 nov',''))}${tsec('Citas y chequeos','calendar','pk',row('gray','calendar','Ortopedia · Dr. Mejía','12 nov · 9:00 a. m.',''))}${tsec('Documentos','file','sky',row('gray','fileText','Orden médica · Resonancia','28 oct',''))}${tsec('Check-ins','heart','em',`<div class="row g8">${mood('mal',30)}${mood('regular',30)}${mood('bien',30)}${mood('bien',30)}<span class="s grow">De «Mal» a «Bien»: mejorando esta semana</span></div>`)}${tsec('Síntomas','activity','gray',row('gray','activity','Dolor de rodilla · leve','1 nov · después de caminar',''))}`;
P.m('Detalle de tratamiento',phone(`${mback('Tratamiento',`<div class="iconbtn">${ic('more',18,'#475569')}</div>`)}${card(`<div class="row g16"><div class="tile lg t-vi">${ic('activity',24,'currentColor',2.2)}</div><div class="grow"><div class="h2" style="font-size:19px">Rodilla derecha</div><div class="sub">Inicio 10 oct · En curso</div></div>${chip('Activo','b')}</div>`)}${tdetail()}`,{tab:'mas'}));
/* web */
const side=()=>`<div class="col" style="width:408px">${head(1,true)}${card(`<div class="h3">Tus misiones</div>${row('sky','activity','Realizar tu resonancia','Paso 2 de 4',chip('En curso','b'))}${row('am','pill','Conseguir tu Metformina','Paso 2 de 4',chip('En curso','b'))}${row('gr','check','Hemograma','Terminada el 2 nov',chip('Lista','gr'))}${row('gr','check','Control de cardiología','Terminada el 12 sep',chip('Lista','gr'))}${btn('Nueva misión','sec block',ic('plus',16,'#2563EB',2.4))}`)}<div class="ey" style="color:var(--tx2)">SUGERIDAS · DE TU EXAMEN DE SANGRE</div>${suggest()}</div>`;
