P.w('Paso 3 · ¿Pudiste realizarte el examen?',web({sel:'misiones',title:'Misiones',sub:'Vamos a realizar tu examen',over:wover(`${sheetHead('b','activity','PASO 3 DE 4','Realizar el examen')}<div class="h2" style="font-size:19px">¿Pudiste realizarte el examen?</div><div class="sub">Vie 6 nov · 7:30 a. m. · Clínica Central</div><div class="row g10">${btn('Sí, me lo hice','grow',ic('check',17,'#fff',3))}${btn('No pude, reprogramar','sec grow')}</div>${hint('No lo marcamos solos aunque haya pasado la fecha.','happy')}`,'top:200px')},`<div class="cols"><div class="grow">${timeline(true,2)}</div>${side()}</div>`),'Web: después del MVP (DU-12).');
